{"file_path":"tests/test_metrics.py","content":"import pytest

from safety_evals.loader import (
    daily_flag_counts,
    dedupe_transcripts,
    parse_transcript_log,
)
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}, {"flagged": False}]) == pytest.approx(1 / 3)


def test_monitor_flag_rate_empty():
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}] * 3,
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2], 8) == 3
    assert flags_in_window([1, 2], 0) == 0


def test_parse_transcript_log_field_values_and_skipped_lines():
    assert parse_transcript_log([
        " # comment",
        "   ",
        " x1 , 3 , 1 ",
        "x2,4,0",
        "x3,5,",
    ]) == [
        {"id": "x1", "day": 3, "flagged": True},
        {"id": "x2", "day": 4, "flagged": False},
        {"id": "x3", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,nope,1"])
def test_parse_transcript_log_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match="line 2"):
        parse_transcript_log(["# header", bad_line])


def test_dedupe_transcripts_uses_last_record_for_duplicate_id():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "a", "day": 3, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [events[1], events[2]]


def test_daily_flag_counts_inclusive_range_and_empty_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 2, "flagged": False},
        {"id": "c", "day": 2, "flagged": True},
        {"id": "d", "day": 4, "flagged": True},
        {"id": "e", "day": 8, "flagged": True},
    ]
    assert daily_flag_counts(events, 2, 5) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 3, 2) == []


def test_monitor_summary_matches_specification():
    groups = {
        "a": [{"id": "x", "day": 1, "flagged": True}],
        "b": [
            {"id": "y", "day": 3, "flagged": False},
            {"id": "z", "day": 4, "flagged": True},
        ],
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {
        "z": [{"flagged": True}],
        "b": [{"flagged": False}],
        "a": [{"flagged": False}],
        "empty": [],
    }
    assert top_flagged_groups(groups, 3) == ["z", "a", "b"]


def test_flag_rate_by_group_sorts_keys_and_marks_empty_groups_none():
    assert flag_rate_by_group({"z": [], "b": [{"flagged": False}], "a": [{"flagged": True}]}) == {
        "a": 1.0,
        "b": 0.0,
        "z": None,
    }


def test_longest_flag_streak_resets_after_zero():
    assert longest_flag_streak([1, 2, 0, 3, 4, 5, 0]) == 3
    assert longest_flag_streak([]) == 0
